//! The FitsTables a FitsChan holds, against C (fitschan.c): `put_table`,
//! `put_tables`, `get_tables` and `remove_tables`, and the tables in a
//! copy, an emptied FitsChan and the native dump.
//!
//! Each case is a script of operations run through the C library by
//! `tools/oracle_fixtures/fitschan_tables_probe.c`, which records the
//! result of each and dumps at the marked points; the same script is run
//! here through the public API and the two transcripts compared byte for
//! byte. The probe's header describes the operations.
//! `fitschan_tables_oracle/cases.rs` is generated by the probe.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "fitschan_tables_oracle/cases.rs"]
mod cases;

use ast_core::error::AstError;
use ast_core::{
    AnyObject, AstType, FitsChan, FitsTable, KeyMap, from_native_string, to_native_string,
};

/// A FitsTable with one integer column named `col`, holding 1 in row 1.
fn table(col: &str) -> FitsTable {
    let mut ft = FitsTable::new();
    ft.add_column(col, AstType::Int, &[], " ").unwrap();
    ft.put_0i(&format!("{col}(1)"), 1, None).unwrap();
    ft
}

/// The text the probe prints for an operation that returns nothing.
fn unit(r: Result<(), AstError>) -> (String, Option<AstError>) {
    ("=\n".to_string(), r.err())
}

/// The dump the probe writes, each line prefixed by "|".
fn dump(fc: &FitsChan) -> String {
    to_native_string(&AnyObject::FitsChan(Box::new(fc.clone())))
        .unwrap()
        .lines()
        .map(|l| format!("|{l}\n"))
        .collect()
}

/// Run one operation, returning its result text and any error.
fn run(fc: &mut FitsChan, op: &str) -> (String, Option<AstError>) {
    let f: Vec<&str> = op.splitn(6, '|').collect();
    let key = f.get(1).copied().unwrap_or("");
    match f[0] {
        "PT" => unit(fc.put_table(&table(f[2]), key)),
        "PTS" => {
            let mut km = KeyMap::new();
            for entry in key.split(',') {
                let (k, val) = entry.split_once('=').unwrap();
                if let Some(n) = val.strip_prefix('#') {
                    km.put_0i(k, n.parse().unwrap(), None).unwrap();
                } else if let Some(col) = val.strip_prefix('*') {
                    let pair = (0..2)
                        .map(|_| Some(AnyObject::FitsTable(Box::new(table(col)))))
                        .collect();
                    km.put_1a(k, pair, None).unwrap();
                } else if val == "?" {
                    km.put_0a(k, AnyObject::KeyMap(Box::new(KeyMap::new())), None)
                        .unwrap();
                } else {
                    km.put_0a(k, AnyObject::FitsTable(Box::new(table(val))), None)
                        .unwrap();
                }
            }
            unit(fc.put_tables(&km))
        }
        "GT" => match fc.get_tables() {
            None => ("= null\n".to_string(), None),
            Some(km) => {
                let mut s = format!("= {}", km.map_size());
                for i in 0..km.map_size() {
                    let k = km.map_key(i).unwrap();
                    s.push_str(&format!(" {k}:"));
                    match km.get_0a(&k).unwrap() {
                        Some(Some(AnyObject::FitsTable(t))) => {
                            s.push_str(&t.as_table().column_name(1).unwrap())
                        }
                        Some(Some(AnyObject::KeyMap(_))) => s.push_str("KeyMap"),
                        _ => {}
                    }
                }
                (s + "\n", None)
            }
        },
        "RT" => unit(fc.remove_tables(key)),
        "PF" => unit(fc.put_fits(key, false)),
        "EF" => unit(fc.empty_fits()),
        "PC" => unit(fc.put_cards(key)),
        "CP" => {
            *fc = fc.clone();
            unit(Ok(()))
        }
        "RW" => {
            let text = to_native_string(&AnyObject::FitsChan(Box::new(fc.clone()))).unwrap();
            let obj = from_native_string(&text).unwrap();
            let name = match &obj {
                AnyObject::FitsChan(_) => "FitsChan",
                _ => "another class",
            };
            if let AnyObject::FitsChan(read) = obj {
                *fc = *read;
            }
            (format!("= {name}\n"), None)
        }
        "D" => (format!("=\n{}", dump(fc)), None),
        other => panic!("operation {other} is not handled"),
    }
}

#[test]
fn fitschan_tables_match_c() {
    let mut failed = Vec::new();
    for &(name, ops, want) in cases::CASES {
        let mut fc = FitsChan::new();
        let mut out = String::new();
        for op in ops {
            out.push_str(&format!("> {op}\n"));
            let (text, err) = run(&mut fc, op);
            out.push_str(&text);
            if let Some(e) = err {
                out.push_str(&format!("! {}\n", e.code() as u32));
            }
        }
        if out != want {
            let line = out
                .lines()
                .zip(want.lines())
                .position(|(a, b)| a != b)
                .unwrap_or_else(|| out.lines().count().min(want.lines().count()));
            failed.push(format!(
                "{name}: first difference at line {}\n--- rust\n{}\n--- C\n{}",
                line + 1,
                out.lines()
                    .skip(line.saturating_sub(3))
                    .take(8)
                    .collect::<Vec<_>>()
                    .join("\n"),
                want.lines()
                    .skip(line.saturating_sub(3))
                    .take(8)
                    .collect::<Vec<_>>()
                    .join("\n"),
            ));
        }
    }
    assert!(failed.is_empty(), "{}", failed.join("\n\n"));
}
